<?php
declare(strict_types=1);
// Synthetic in-memory data only. No production cookies, names or scores.
require __DIR__.'/../server/Leaderboard.php';
use StarRebound\Leaderboard;
use StarRebound\ApiError;
$results=[];$clock=1000.0;
function check($ok,$message){if(!$ok)throw new RuntimeException($message);}
function test($name,$fn){global $results;try{$fn();$results[]=['name'=>$name,'status'=>'PASS'];}catch(Throwable $e){$results[]=['name'=>$name,'status'=>'FAIL','message'=>$e->getMessage()];}}
function setup(){ $db=new PDO('sqlite::memory:');return [$db,new Leaderboard($db,fn()=>$GLOBALS['clock'])]; }
function automatic($s,$actor,$score=120,$difficulty='nightmare'){
 $r=$s->start($actor,$difficulty);$GLOBALS['clock']+=20;
 return ['runId'=>$r['runId'],'nonce'=>$r['nonce'],'difficulty'=>$difficulty,'ruleset'=>$r['ruleset'],'seed'=>$r['seed'],'score'=>$score,'time'=>16.0,'result'=>'lost','stageIndex'=>0,'completedStages'=>0,'hp'=>0,'kills'=>$score?1:0,'returned'=>0,'bestCombo'=>$score?1:0,'hits'=>5,'captureUses'=>0,'details'=>['version'=>1,'heals'=>0,'scoreBreakdown'=>['defeats'=>$score,'returns'=>0,'lifeBonus'=>0]]];
}
function renameInput($p,$name){return ['runId'=>$p['runId'],'nonce'=>$p['nonce'],'name'=>$name];}
function rejects($fn,$status){try{$fn();throw new RuntimeException('invalid request accepted');}catch(ApiError $e){check($e->status===$status,'unexpected rejection status');}}

test('automatic registration assigns distinct numbered aliases and retries one immutable result',function(){[$db,$s]=setup();$p=automatic($s,'one');$a=$s->finishAuto('one',$p);check($a['entry']['name']==='星の方舟1','first numbered alias missing');check($a===$s->finishAuto('one',$p),'retry response changed');$b=$s->finishAuto('two',automatic($s,'two'));check($b['entry']['name']==='星の方舟2','alias not unique');check((int)$db->query('SELECT COUNT(*) FROM scores')->fetchColumn()===2,'duplicate rows');$changed=$p;$changed['score']=240;$changed['details']['scoreBreakdown']['defeats']=240;rejects(fn()=>$s->finishAuto('one',$changed),409);});
test('one browser retains its alias across difficulties and does not replace a better score or details',function(){[$db,$s]=setup();$p=automatic($s,'one',240);$a=$s->finishAuto('one',$p);$id=$db->query('SELECT id FROM scores')->fetchColumn();$b=$s->finishAuto('one',automatic($s,'one',120));check(!$b['improved']&&$a['entry']===$b['entry'],'lower score replaced best or details');check($id===$db->query('SELECT id FROM scores')->fetchColumn(),'score identity changed');$easy=$s->finishAuto('one',automatic($s,'one',120,'easy'));check($easy['entry']['name']==='星の方舟1','alias changed by difficulty');});
test('rename changes owned nickname only and persists into future automatic results',function(){[$db,$s]=setup();$p=automatic($s,'one',240);$s->finishAuto('one',$p);$s->finishAuto('one',automatic($s,'one',120,'easy'));$before=$db->query('SELECT id,browser,difficulty,ruleset,score,stage,cleared,recorded FROM scores ORDER BY id')->fetchAll();$details=$db->query('SELECT * FROM score_details ORDER BY score_id')->fetchAll();$renamed=$s->rename('one',renameInput($p,'合成の舟'));check($renamed['entry']['name']==='合成の舟','nickname not updated');check($before===$db->query('SELECT id,browser,difficulty,ruleset,score,stage,cleared,recorded FROM scores ORDER BY id')->fetchAll(),'rename changed score or tie order');check($details===$db->query('SELECT * FROM score_details ORDER BY score_id')->fetchAll(),'rename changed details');check($s->finishAuto('one',$p)['entry']['name']==='合成の舟','uncertain automatic retry reverts nickname');check($s->top('easy')['entries'][0]['name']==='合成の舟','owned difficulty retained stale nickname');check($s->finishAuto('one',automatic($s,'one',360))['entry']['name']==='合成の舟','future best lost registered name');});
test('legacy names and canonical retry contracts survive automatic registration',function(){[$db,$s]=setup();$p=automatic($s,'legacy',240);$p['name']='昔の合成舟';$old=$s->finish('legacy',$p);$lower=$s->finishAuto('legacy',automatic($s,'legacy',120));check($lower['entry']===$old['entry'],'legacy best or name changed');check($s->finish('legacy',$p)===$old,'legacy retry changed');check((int)$db->query('PRAGMA user_version')->fetchColumn()===1,'base schema became unreadable to old server');});
test('rename rejects another browser, bad nonce, pending runs, expired runs and malformed names',function(){[$db,$s]=setup();$p=automatic($s,'one');$s->finishAuto('one',$p);$before=$s->top('nightmare');rejects(fn()=>$s->rename('other',renameInput($p,'偽の舟')),403);$bad=renameInput($p,'偽の舟');$bad['nonce']=str_repeat('0',64);rejects(fn()=>$s->rename('one',$bad),403);$pending=automatic($s,'pending');rejects(fn()=>$s->rename('pending',renameInput($pending,'偽の舟')),409);rejects(fn()=>$s->rename('one',renameInput($p,'<bad>')),422);$GLOBALS['clock']+=7201;rejects(fn()=>$s->rename('one',renameInput($p,'期限外')),410);check($before===$s->top('nightmare'),'rejected rename changed ranking');});
test('automatic endpoint cannot accept a client-selected nickname or another actors result',function(){[$db,$s]=setup();$p=automatic($s,'one');$spoof=$p;$spoof['name']='偽の舟';rejects(fn()=>$s->finishAuto('one',$spoof),422);rejects(fn()=>$s->finishAuto('other',$p),403);check((int)$db->query('SELECT COUNT(*) FROM scores')->fetchColumn()===0,'invalid auto registered');check($s->finishAuto('one',$p)['entry']['name']==='星の方舟1','rejected auto allocated an alias');});
test('failed details write rolls back alias allocation, score and completed run',function(){[$db,$s]=setup();$p=automatic($s,'one');$db->exec("CREATE TRIGGER fail_details BEFORE INSERT ON score_details BEGIN SELECT RAISE(ABORT,'synthetic failure'); END");try{$s->finishAuto('one',$p);throw new RuntimeException('failure not injected');}catch(PDOException){}check((int)$db->query('SELECT COUNT(*) FROM scores')->fetchColumn()===0,'partial score persisted');$db->exec('DROP TRIGGER fail_details');check($s->finishAuto('one',$p)['entry']['name']==='星の方舟1','failed transaction consumed numbered alias');});
test('rename is repeatable and cannot mutate another browsers score',function(){[$db,$s]=setup();$p=automatic($s,'one');$s->finishAuto('one',$p);$other=$s->finishAuto('two',automatic($s,'two'));$s->rename('one',renameInput($p,'新しい舟'));$s->rename('one',renameInput($p,'新しい舟'));$s->rename('one',renameInput($p,'次の舟'));check($s->top('nightmare')['entries'][1]===$other['entry'],'rename changed foreign score');check($s->finishAuto('one',automatic($s,'one',240))['entry']['name']==='次の舟','second rename did not persist');});
$failed=count(array_filter($results,fn($r)=>$r['status']==='FAIL'));echo json_encode(['failed'=>$failed,'results'=>$results],JSON_UNESCAPED_UNICODE|JSON_PRETTY_PRINT);exit($failed?1:0);
